@push('styles')
<style>
.doc-workspace [hidden]{display:none!important}
.doc-workspace{width:100%;max-width:none;min-width:0;color:var(--text-primary,#17243b)}.doc-workspace *{box-sizing:border-box}.doc-workspace .panel{margin:16px 0;padding:22px}.doc-workspace h2{font-size:20px;line-height:1.35}.doc-workspace h3{font-size:16px;line-height:1.4}.doc-workspace p{line-height:1.55}.doc-workspace .muted{color:var(--text-muted,#64748b);font-size:13px}.doc-workspace .cta{display:inline-flex;align-items:center;justify-content:center;min-height:42px;text-decoration:none;font-weight:600}.doc-workspace .cta:disabled{opacity:.45;cursor:not-allowed}.doc-workspace .doc-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.doc-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 20px;border-bottom:1px solid var(--border-color,#ddd);padding-bottom:10px}.doc-tabs a{padding:8px 14px;border-radius:8px;text-decoration:none;color:var(--text-primary,#17243b);font-size:13px}.doc-tabs a[aria-current=page]{background:#233f88;color:#fff;font-weight:600}.doc-workspace .doc-counts{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.doc-workspace .doc-counts a{border:1px solid var(--border-color,#ddd);background:var(--card-bg,#fff);border-radius:10px;padding:12px 18px;color:inherit;text-decoration:none;font-size:13px}.doc-workspace .doc-counts strong{font-size:20px;margin-right:8px}.doc-workspace .doc-card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));gap:16px}.doc-workspace .doc-card{display:flex;flex-direction:column;min-width:0;background:var(--card-bg,#fff);border:1px solid var(--border-color,#ddd);border-radius:14px;padding:20px;gap:12px}.doc-workspace .doc-card h2{font-size:17px;overflow-wrap:anywhere}.doc-workspace .doc-card footer{margin-top:auto}.doc-workspace .doc-state{display:inline-flex;align-items:center;border-radius:6px;padding:4px 8px;font-size:12px;font-weight:600;background:var(--hover-bg,#eef2f8);color:var(--text-primary,#17243b)}.doc-workspace .doc-state.BORRADOR{background:#fff3d8;color:#805200}.doc-workspace .doc-state.ACTIVA{background:#e6f5ec;color:#19623d}.doc-workspace .doc-card ul{list-style:none;padding:0;margin:0;font-size:12px;color:var(--text-muted,#64748b)}.doc-workspace .doc-card li{padding:4px 0;overflow-wrap:anywhere}.doc-workspace progress{width:100%;height:7px;accent-color:#227448}.doc-workspace .doc-empty{padding:40px 24px;text-align:center;background:var(--card-bg,#fff);border:1px dashed var(--border-color,#ddd);border-radius:14px}.doc-workspace .doc-empty .actions{justify-content:center;margin-top:18px}.doc-workspace .doc-filter{display:grid;grid-template-columns:minmax(160px,1fr) minmax(150px,220px) auto;gap:12px;align-items:end}.doc-workspace label{line-height:1.5}.doc-workspace label :is(input,select){margin-top:5px}.doc-workspace :focus-visible{outline:3px solid #458bef;outline-offset:3px}.doc-workspace .doc-review-grid{display:grid;grid-template-columns:minmax(270px,.8fr) minmax(0,1.8fr);gap:18px;align-items:start}.doc-workspace .doc-review-grid>.panel{min-width:0;margin:0}.doc-workspace .doc-list{list-style:none;padding:0;margin:12px 0;max-height:650px;overflow:auto}.doc-workspace .doc-list li{border-bottom:1px solid var(--border-color,#ddd)}.doc-workspace .doc-list a{display:block;padding:14px 12px;text-decoration:none;color:inherit;border-left:3px solid transparent;overflow-wrap:anywhere;font-size:13px}.doc-workspace .doc-list a[aria-current=true]{background:var(--hover-bg,#f0f4fc);border-left-color:#315dd1}.doc-workspace .doc-list small{display:block;margin-top:5px;color:var(--text-muted,#64748b)}.doc-workspace .doc-review-title{overflow-wrap:anywhere;font-size:16px}.doc-workspace .pdf-frame{width:100%;height:62vh;min-height:380px;border:1px solid var(--border-color,#ddd);border-radius:8px;background:#f4f5f7}.doc-workspace .doc-review-status{padding:9px 0;font-size:12px;color:var(--text-muted,#64748b)}.doc-workspace .doc-confirm{padding:16px 0 0;margin-top:12px;border-top:1px solid var(--border-color,#ddd)}.doc-workspace .doc-confirm button{margin-top:12px}.doc-workspace .doc-danger{color:#b32626;background:transparent;border:1px solid #dc8e8e}.doc-workspace .doc-version-links{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.doc-workspace dialog{width:min(96vw,1500px);max-width:96vw;height:94vh;max-height:94vh;margin:auto;border:1px solid var(--border-color,#ddd);border-radius:14px;padding:18px;background:var(--card-bg,#fff);color:inherit}.doc-workspace dialog::backdrop{background:rgba(10,20,35,.65)}.doc-workspace dialog .pdf-frame{height:calc(94vh - 100px)}.doc-workspace .doc-reference-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:14px;padding:12px 0;border-top:1px solid var(--border-color,#ddd);font-size:13px;overflow-wrap:anywhere}.dark-mode .doc-workspace .doc-danger{color:#ffb5b5}.doc-workspace .doc-field-hint{font-size:12px;color:var(--text-muted,#64748b);margin:8px 0}
@media(max-width:1000px){.doc-workspace .doc-review-grid{grid-template-columns:1fr}.doc-workspace .doc-list{max-height:260px}.doc-workspace .doc-filter{grid-template-columns:1fr 1fr}.doc-workspace .doc-filter>label:first-child{grid-column:1/-1}}
@media(max-width:600px){.doc-workspace .panel{padding:16px}.doc-workspace .doc-filter,.doc-workspace .fields{grid-template-columns:1fr}.doc-workspace .doc-toolbar{align-items:flex-start}.doc-workspace .cta{min-height:44px}.doc-workspace .doc-reference-row{grid-template-columns:1fr}.doc-workspace .pdf-frame{height:52vh;min-height:320px}.doc-workspace .doc-counts{gap:8px}.doc-workspace .doc-counts a{padding:10px 12px}}
</style>
@endpush
